/**
 * Generates the reading copies of the course outlines (ported from the ASMC reference's
 * scripts/curriculum-doc.mjs, made multi-subject):
 *   docs/curriculum/<subject>.md   one per course file in src/data/course/ (site.md for site chapters)
 *   docs/curriculum/coverage.md    curriculum code → chapters matrix, plus the uncovered in-scope codes
 *   docs/curriculum/cross-subject.md  every prereq edge between subjects
 * The JSON is the source of truth; never edit the generated files. With no course files yet it still
 * writes coverage.md and cross-subject.md (saying so) and removes stale per-subject pages.
 * Plain Node (no TypeScript, no Vite), so it reads the JSON itself; the schema checks live in tests/.
 *
 * Run: npm run docs:curriculum        (node scripts/curriculum-doc.mjs)
 * Use from a test: import { generate } from '../scripts/curriculum-doc.mjs' → { files, stale }.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const SUBJECT_ORDER = ['site', 'math', 'physics', 'chemistry', 'biology', 'earth', 'inquiry', 'history', 'geography', 'civics', 'social', 'chinese'];
const COVERING = new Set(['teaches', 'reviews']);

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const listJson = (dir) => (fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => f.endsWith('.json')).sort() : []);
const esc = (s) => String(s ?? '').replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
const both = (l) => (l ? `${esc(l['zh-tw'])} / ${esc(l.en)}` : '');
const hours = (min) => Math.round((min / 60) * 2) / 2;
const n = (count, word) => `${count} ${word}${count === 1 ? '' : 's'}`;

/** Everything the docs are built from, read from `root` (the project folder). */
export function load(root) {
  const data = path.join(root, 'src', 'data');
  const courseDir = path.join(data, 'course');
  const courses = listJson(courseDir)
    .filter((f) => f !== 'waivers.json')
    .map((f) => ({ file: `src/data/course/${f}`, ...readJson(path.join(courseDir, f)) }))
    .sort((a, b) => SUBJECT_ORDER.indexOf(a.subject) - SUBJECT_ORDER.indexOf(b.subject));
  const subjects = readJson(path.join(data, 'subjects.json'));
  const codeDir = path.join(data, 'registry', 'codes');
  // <domain>.json files are CodeEntry[]; overrides.json (manual corrections, already applied) is not.
  const codes = listJson(codeDir)
    .filter((f) => f !== 'overrides.json')
    .flatMap((f) => {
      const list = readJson(path.join(codeDir, f));
      return Array.isArray(list) ? list : [];
    });
  const sourcesFile = path.join(data, 'registry', 'sources.json');
  const sources = fs.existsSync(sourcesFile) ? readJson(sourcesFile) : [];
  const terms = new Map();
  const walk = (d) => {
    if (!fs.existsSync(d)) return;
    for (const n of fs.readdirSync(d).sort()) {
      const p = path.join(d, n);
      if (fs.statSync(p).isDirectory()) walk(p);
      else if (n.endsWith('.json')) for (const t of readJson(p).terms ?? []) terms.set(t.id, t);
    }
  };
  walk(path.join(data, 'terms'));
  const waiversFile = path.join(courseDir, 'waivers.json');
  const waivers = fs.existsSync(waiversFile) ? readJson(waiversFile) : [];
  return { courses, subjects, codes, sources, terms, waivers };
}

/** Flatten the outlines into chapters with global ids, part numbers and resolved paths. */
function flatten(courses, subjects) {
  const pathsOf = (s) => subjects.find((x) => x.id === s)?.paths.map((p) => p.id) ?? [];
  const chapters = [];
  for (const c of courses)
    for (const part of c.parts)
      part.chapters.forEach((ch, i) =>
        chapters.push({
          ...ch,
          id: `${c.subject}/${ch.slug}`,
          subject: c.subject,
          part,
          num: `${part.num}.${i + 1}`,
          track: !part.track || part.track === 'core' ? 'core' : part.track.id,
          onPaths: c.subject === 'site' ? [] : (ch.paths ?? pathsOf(c.subject)),
          codes: ch.codes ?? [],
          prereqs: ch.prereqs ?? [],
          newConcepts: ch.newConcepts ?? [],
        }),
      );
  return chapters;
}

const termLabel = (terms, id) => {
  const t = terms.get(id);
  return t ? `${esc(t.zh)} ${esc(t.en)}` : `\`${id}\``;
};
const codeLabel = (r) => `\`${r.key}\`${r.role && r.role !== 'teaches' ? ` (${r.role})` : ''}${r.part ? ` [${esc(r.part)}]` : ''}${r.case ? ` {${esc(r.case)}}` : ''}`;
const header = (what, from) => [`<!-- GENERATED by scripts/curriculum-doc.mjs from ${from}. Do not edit; edit the JSON and run npm run docs:curriculum. -->`, '', what, ''];

function subjectDoc(course, ctx) {
  const { subjects, terms, sources, chapters } = ctx;
  const subject = subjects.find((s) => s.id === course.subject);
  const mine = chapters.filter((c) => c.subject === course.subject);
  const byId = new Map(chapters.map((c) => [c.id, c]));
  const srcTitle = new Map(sources.map((s) => [s.id, s]));
  const core = course.parts.filter((p) => !p.track || p.track === 'core');
  const tracks = course.parts.filter((p) => p.track && p.track !== 'core');
  const minutes = mine.reduce((a, c) => a + (c.minutes ?? 0), 0);
  const title = subject ? both(subject.title) : course.subject === 'site' ? '網站 / Site' : course.subject;
  const L = header(`# ${title}: course outline`, course.file);
  L.push(
    `**Version ${course.version}, ${course.date}.** ${n(course.parts.length, 'part')}, ${n(mine.length, 'chapter')}, about ${n(hours(minutes), 'hour')} of lessons.  `,
    `Core: ${n(core.length, 'part')}, ${n(mine.filter((c) => c.track === 'core').length, 'chapter')}. Tracks: ${tracks.length ? [...new Set(tracks.map((p) => p.track.id))].join(', ') : 'none'}.  `,
  );
  if (subject) L.push(`Papers: ${subject.papers.join(', ')}. Paths: ${subject.paths.map((p) => `${esc(p.label['zh-tw'])} (\`${p.id}\`)`).join(', ')}. Status: ${subject.status}.`);
  L.push('');
  if (course.decisions?.length) L.push('## Decisions', '', ...course.decisions.map((d) => `- ${esc(d)}`), '');
  if (course.openQuestions?.length) L.push('## Open questions', '', ...course.openQuestions.map((q, i) => `${i + 1}. ${esc(q)}`), '');
  L.push('## Parts', '', '| Part | Title | Track | Chapters | Question |', '|---|---|---|---|---|');
  for (const p of course.parts) L.push(`| ${p.num} | ${both(p.title)} | ${!p.track || p.track === 'core' ? 'core' : `**${esc(p.track.id)}**`} | ${p.chapters.length} | ${both(p.question)} |`);
  L.push('');
  for (const p of course.parts) {
    const track = p.track && p.track !== 'core' ? p.track : null;
    L.push(`### Part ${p.num}: ${both(p.title)}${track ? ` (track ${esc(track.id)})` : ''}`, '', `**Question:** ${both(p.question)}  `);
    if (track) L.push(`**Track:** ${both(track.title)}. Starts after ${track.entry.after.map((a) => `\`${a}\``).join(', ') || '(anywhere)'}: ${both(track.entry.note)}  `);
    L.push('', `*Why here:* ${esc(p.whyHere)}`, '', '| # | Chapter | Kind | Paths | Min | Codes | New ideas | Needs |', '|---|---|---|---|---|---|---|---|');
    for (const ch of p.chapters) {
      const c = byId.get(`${course.subject}/${ch.slug}`);
      const needs = c.prereqs.map((id) => {
        const d = byId.get(id);
        return d && d.subject === course.subject ? d.num : `\`${id}\``;
      });
      L.push(
        `| ${c.num} | **${esc(ch.title['zh-tw'])}**<br>${esc(ch.title.en)}<br>\`${ch.slug}\` | ${ch.kind}${(ch.marks ?? []).length ? ` ${ch.marks.join('')}` : ''} | ${ch.paths ? ch.paths.join(', ') : 'all'} | ${ch.minutes} | ${c.codes.map(codeLabel).join('<br>') || '–'} | ${c.newConcepts.map((t) => termLabel(terms, t)).join('<br>') || '–'} | ${needs.join(', ') || '–'} |`,
      );
    }
    const cited = [...new Set(p.chapters.flatMap((c) => c.sources ?? []))];
    L.push('', `Sources: ${cited.map((s) => (srcTitle.has(s) ? `[${esc(srcTitle.get(s).title)}](${srcTitle.get(s).url})` : `\`${s}\``)).join('; ') || '–'}`, '');
  }
  return L.join('\n');
}

function coverageDoc(ctx) {
  const { subjects, codes, chapters, courses, waivers } = ctx;
  const withCourse = new Set(courses.map((c) => c.subject));
  const L = header('# Curriculum code coverage', 'src/data/course/*.json and src/data/registry/codes/*.json');
  L.push(
    'A code is covered when a chapter of its subject teaches or reviews it (role `teaches` or `reviews`) on every path it is examined on: 數A-only codes on `mathA`, 數B-only codes on `mathB`, the rest on every path of the subject. tests/curriculum/coverage.test.ts enforces this for every subject that has a course file.',
    '',
  );
  if (!courses.length) L.push('**No course files yet** (they are written at S1/M1), so every in-scope code is still uncovered.', '');
  if (!codes.length) L.push('**No code registry yet** (src/data/registry/codes/).', '');
  const rows = [];
  const sections = [];
  for (const s of subjects) {
    const inScope = codes.filter((c) => c.inGsat === 'yes' && c.subjects.includes(s.id));
    if (!inScope.length) continue;
    const all = s.paths.map((p) => p.id);
    const missing = [];
    const lines = ['| Code | Title | Track | Marks | Chapters |', '|---|---|---|---|---|'];
    for (const code of inScope) {
      const refs = chapters.filter((ch) => ch.subject !== 'site' && code.subjects.includes(ch.subject) && ch.codes.some((r) => r.key === code.key));
      const required = code.gsatTrack === 'A' ? ['mathA'] : code.gsatTrack === 'B' ? ['mathB'] : all;
      const covering = refs.filter((ch) => ch.codes.some((r) => r.key === code.key && COVERING.has(r.role ?? 'teaches')));
      const off = required.filter((p) => !covering.some((ch) => ch.onPaths.includes(p)));
      if (off.length) missing.push({ code, off });
      const list = refs.map((ch) => `\`${ch.id}\` (${ch.codes.filter((r) => r.key === code.key).map((r) => r.role ?? 'teaches').join(', ')})`).join('<br>');
      lines.push(`| \`${code.key}\` ${esc(code.code)} | ${esc(code.title?.['zh-tw'])} | ${code.gsatTrack} | ${(code.marks ?? []).join('') || '–'} | ${list || (off.length ? '**uncovered**' : '–')} |`);
    }
    rows.push(`| ${esc(s.title['zh-tw'])} ${esc(s.title.en)} | ${withCourse.has(s.id) ? 'yes' : 'no'} | ${inScope.length} | ${inScope.length - missing.length} | ${missing.length} |`);
    sections.push(`## ${both(s.title)}`, '', `${inScope.length - missing.length}/${inScope.length} in-scope codes covered.`, '');
    if (missing.length) sections.push('**Uncovered:**', '', ...missing.map((m) => `- \`${m.code.key}\` ${esc(m.code.title?.['zh-tw'])}: not taught or reviewed on ${m.off.join(', ')}`), '');
    sections.push(...lines, '');
  }
  if (rows.length) L.push('## Summary', '', '| Subject | Course file | In-scope codes | Covered | Uncovered |', '|---|---|---|---|---|', ...rows, '');
  L.push(...sections);
  L.push('## Waivers', '', waivers.length ? '| From | To | Reason | Approved by |\n|---|---|---|---|' : 'None (src/data/course/waivers.json is empty).');
  for (const w of waivers) L.push(`| \`${w.from}\` | \`${w.to}\` | ${esc(w.reason)} | ${esc(w.approvedBy)} |`);
  L.push('');
  return L.join('\n');
}

function crossSubjectDoc(ctx) {
  const { chapters } = ctx;
  const byId = new Map(chapters.map((c) => [c.id, c]));
  const edges = chapters.flatMap((c) => c.prereqs.map((p) => [c, byId.get(p), p]).filter(([, d]) => d && d.subject !== c.subject && d.subject !== 'site'));
  const L = header('# Cross-subject prerequisites', 'src/data/course/*.json');
  L.push(
    'Edges where a chapter needs a chapter of another subject (site chapters are left out: every subject builds on them). Such a prereq must be a bridge or core chapter on every path of its subject (tests/curriculum/no-jump.test.ts).',
    '',
  );
  if (!edges.length) L.push(chapters.length ? 'None.' : '**No course files yet.**', '');
  else L.push('| Chapter | Needs | Kind |', '|---|---|---|', ...edges.map(([c, d]) => `| \`${c.id}\` ${esc(c.title['zh-tw'])} | \`${d.id}\` ${esc(d.title['zh-tw'])} | ${d.kind} |`), '');
  return L.join('\n');
}

/** Build every generated file in memory. `stale` lists per-subject pages whose course file is gone. */
export function generate(root) {
  const ctx = load(root);
  ctx.chapters = flatten(ctx.courses, ctx.subjects);
  const out = 'docs/curriculum';
  const files = [
    ...ctx.courses.map((c) => ({ path: `${out}/${c.subject}.md`, content: subjectDoc(c, ctx) })),
    { path: `${out}/coverage.md`, content: coverageDoc(ctx) },
    { path: `${out}/cross-subject.md`, content: crossSubjectDoc(ctx) },
  ];
  const dir = path.join(root, out);
  const keep = new Set(files.map((f) => path.basename(f.path)));
  const stale = fs.existsSync(dir)
    ? fs
        .readdirSync(dir)
        .filter((f) => SUBJECT_ORDER.includes(f.replace(/\.md$/, '')) && !keep.has(f))
        .map((f) => `${out}/${f}`)
    : [];
  return { files, stale };
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  const root = fileURLToPath(new URL('../', import.meta.url));
  const { files, stale } = generate(root);
  fs.mkdirSync(path.join(root, 'docs', 'curriculum'), { recursive: true });
  for (const f of files) fs.writeFileSync(path.join(root, f.path), f.content);
  for (const f of stale) fs.rmSync(path.join(root, f));
  console.log(`${files.map((f) => `${f.path}: ${f.content.split('\n').length} lines`).join('\n')}${stale.length ? `\nremoved stale: ${stale.join(', ')}` : ''}`);
}
